import itertools

# vertices 0..4
edges = [(0,1),(0,2),(0,3),(0,4),(1,2),(1,3),(1,4),(2,3),(2,4),(3,4)]
n = 10

# fixed: c[3]=1, c[9]=0
fixed = {3:1, 9:0}

# all triangles in K5
triangles = []
for i in range(5):
    for j in range(i+1,5):
        for k in range(j+1,5):
            triangles.append((i,j,k))

def edge_index(i,j):
    if i<j:
        return edges.index((i,j))
    else:
        return edges.index((j,i))

# brute force 2^10 = 1024, easy
for bits in range(1<<n):
    c = [(bits>>i)&1 for i in range(n)]
    # check fixed
    ok = True
    for idx, val in fixed.items():
        if c[idx] != val:
            ok = False
            break
    if not ok:
        continue
    # check no monochromatic triangle
    bad = False
    for (a,b,c_) in triangles:
        e1 = edge_index(a,b)
        e2 = edge_index(a,c_)
        e3 = edge_index(b,c_)
        if c[e1]==c[e2]==c[e3]:
            bad = True
            break
    if not bad:
        print("Found:", c)
        # print edges
        for idx, (i,j) in enumerate(edges):
            print(f"  {i}-{j}: {c[idx]}")
        break
else:
    print("UNSAT")
